//
// Installation information (docs/15 §9.10 `/admin/about` and `/admin/licenses`, 05 §2.11-10, O-L04,
// ADR-0010 C-153, WO-39): the server version and commit, the agent protocol version, the agent
// versions in use, the uptime and the support policy document; and the third-party component lists
// of the server, the UI and the agent (generated by the build, WO-44; a build without them answers
// `available: false, reason: not_generated`). Generated client only; keys start with 'admin'.
import { useQuery } from '@tanstack/react-query';

import { api, unwrap, type EnvelopeOf } from '../client';
import type { components } from '../generated/schema';

export type About = components['schemas']['About'];
export type AboutLicenses = components['schemas']['AboutLicenses'];
export type LicenseSection = components['schemas']['AboutLicenseSection'];
export type LicenseComponent = components['schemas']['AboutLicenseComponent'];

export const LICENSE_PARTS = ['server', 'ui', 'agent'] as const;
export type LicensePart = (typeof LICENSE_PARTS)[number];

export const aboutKeys = {
  about: () => ['admin', 'about'] as const,
  licenses: () => ['admin', 'about', 'licenses'] as const,
};

export async function getAbout() {
  return unwrap<EnvelopeOf<'/api/v1/about', 'get'>>(api().client.GET('/api/v1/about'));
}

export async function getLicenses() {
  return unwrap<EnvelopeOf<'/api/v1/about/licenses', 'get'>>(
    api().client.GET('/api/v1/about/licenses'),
  );
}

export function useAbout() {
  return useQuery({ queryKey: aboutKeys.about(), queryFn: getAbout, staleTime: 30_000 });
}

export function useLicenses() {
  return useQuery({ queryKey: aboutKeys.licenses(), queryFn: getLicenses, staleTime: 300_000 });
}
